def _va(s):
    for a,b in [("aquest","este"),("aquesta","esta"),("Aquest","Este"),("Aquesta","Esta"),("Fes servir","Utilitza"),("fes-ne servir","utilitza'n"),("Fes ","Fes "),
                ("Fes servir","Utilitza"),("pots","pots"),("Escriu","Escriu"),("Comença","Comença"),("Convé","Convé"),("deixa","deixa")]:
        s=s.replace(a,b)
    return s
